//! One independent `#[test]` per `.zu` fixture with a matching `.out`
//! file (generated by `build.rs`, see that file's own docs). A
//! top-level `tests/*.zu` fixture gets an exact stdout+stderr match
//! against its `.out` (`run_fixture`), with `@@ROOT` resolved to this
//! checkout's own canonical root. A fixture in a subdirectory instead
//! gets `run_exit_code_fixture`: its own suite decides pass/fail
//! internally (self-checking assertions, raising on the first real
//! failure) and prints whatever it wants along the way, so the only
//! thing worth asserting from outside is that the process didn't exit
//! non-zero; a golden-output diff would be either infeasible (variable
//! timing, generated keys, wall-clock-dependent behavior) or just
//! redundant with checks the fixture already does itself.

use std::fs;
use std::process::Command;

fn run_fixture(zu_path_str: &str) {
  let manifest_dir = env!("CARGO_MANIFEST_DIR");
  let bin = env!("CARGO_BIN_EXE_zuri");
  // Through the same helper the runtime itself uses, so both sides
  // spell a canonical path identically. Windows' own canonical form
  // carries a `\\?\` prefix that the runtime strips before any of it
  // reaches a diagnostic; expanding `@@ROOT` with the unstripped form
  // would leave the expected text disagreeing with the actual on
  // nothing but that prefix.
  let root = zuri::builtins::file::canonical_path(manifest_dir)
    .expect("crate root should be canonicalizable");

  let out_path_str = format!(
    "{}.out",
    zu_path_str.strip_suffix(".zu").unwrap_or(zu_path_str)
  );
  let expected_raw = fs::read_to_string(&out_path_str)
    .unwrap_or_else(|e| panic!("failed to read {out_path_str}: {e}"));
  let expected = expected_raw.replace("@@ROOT", &root);

  // Shells out through `sh -c '... 2>&1'` (rather than capturing
  // stdout/stderr as separate pipes and concatenating them
  // afterward) specifically to preserve TRUE chronological
  // interleaving between echoed output and an eventual uncaught-
  // error message; exactly what the original script's
  // `"$BIN" "$zu" 2>&1` gave for free via real shell redirection.
  let output = Command::new("sh")
    .arg("-c")
    .arg(format!(
      "{} run {} 2>&1",
      shell_quote(bin),
      shell_quote(zu_path_str)
    ))
    .output()
    .unwrap_or_else(|e| panic!("failed to run zuri on {zu_path_str}: {e}"));
  let actual = String::from_utf8_lossy(&output.stdout).into_owned();

  // Both sides went through a `$(...)` command substitution in the
  // original script, which strips ALL trailing newlines; match that
  // so a lone trailing-newline difference isn't a false failure.
  //
  // Carriage returns go too. A `.gitattributes` rule keeps the `.out`
  // files LF on every platform, but a checkout made with a different
  // git configuration would otherwise fail every golden-output test on
  // a line ending that was never in the repository. No fixture holds a
  // carriage return on purpose, so dropping them costs no coverage.
  let actual = actual.replace("\r\n", "\n");
  let expected = expected.replace("\r\n", "\n");

  // Separators go the same way, for the same reason.
  //
  // A fixture spells every path after `@@ROOT` with a forward slash,
  // but `@@ROOT` expands to a native path, so the expected text ends up
  // mixing both while the runtime's own diagnostics use native
  // separators throughout. The two then differ on nothing but the
  // slashes. No `.out` file in the suite contains a backslash for any
  // other purpose, so on Windows every one of them is a separator and
  // normalising them masks nothing.
  #[cfg(windows)]
  let actual = actual.replace('\\', "/");
  #[cfg(windows)]
  let expected = expected.replace('\\', "/");

  let actual = actual.trim_end_matches(['\n', '\r']);
  let expected = expected.trim_end_matches(['\n', '\r']);
  assert_eq!(
    actual, expected,
    "\n{zu_path_str}\n--- expected ---\n{expected}\n--- actual ---\n{actual}\n"
  );
}

fn run_exit_code_fixture(zu_path_str: &str) {
  let bin = env!("CARGO_BIN_EXE_zuri");
  let output = Command::new("sh")
    .arg("-c")
    .arg(format!(
      "{} run {} 2>&1",
      shell_quote(bin),
      shell_quote(zu_path_str)
    ))
    .output()
    .unwrap_or_else(|e| panic!("failed to run zuri on {zu_path_str}: {e}"));
  assert!(
    output.status.success(),
    "\n{zu_path_str} exited with {}\n--- output ---\n{}\n",
    output.status,
    String::from_utf8_lossy(&output.stdout)
  );
}

fn shell_quote(s: &str) -> String {
  format!("'{}'", s.replace('\'', r"'\''"))
}

// Generated by `build.rs` into `tests/generated/`; a subdirectory,
// not `tests/` itself, so Cargo's top-level test auto-discovery
// doesn't also try (and fail) to compile it as its own standalone
// integration-test binary. See `build.rs`'s own docs on why this path
// is fixed (computable from `CARGO_MANIFEST_DIR` alone) rather than
// routed through `OUT_DIR`.
include!(concat!(
  env!("CARGO_MANIFEST_DIR"),
  "/tests/generated/zu_conformance_generated.rs"
));

/// The launch rules the executable implements: `zuri run` for scripts
/// and packages, a bare first word for a command. Each case builds the
/// tree it needs under Cargo's own test temp directory, so nothing
/// here depends on the shape of the checkout it runs in.
mod launch {
  use std::fs;
  use std::path::{Path, PathBuf};
  use std::process::{Command, Output};

  /// A fresh directory for one case, named after it so a failure says
  /// where to look.
  fn case(name: &str) -> PathBuf {
    let dir = Path::new(env!("CARGO_TARGET_TMPDIR")).join("launch").join(name);

    let _ = fs::remove_dir_all(&dir);
    fs::create_dir_all(&dir).expect("failed to create the case directory");

    dir
  }

  fn write(path: &Path, source: &str) {
    if let Some(parent) = path.parent() {
      fs::create_dir_all(parent).expect("failed to create a fixture directory");
    }

    fs::write(path, source).expect("failed to write a fixture");
  }

  /// Runs the built executable from `cwd`, with stderr folded in so a
  /// launch failure is as readable as ordinary output.
  fn zuri(cwd: &Path, args: &[&str]) -> Output {
    Command::new(env!("CARGO_BIN_EXE_zuri"))
      .args(args)
      .current_dir(cwd)
      .output()
      .expect("failed to run zuri")
  }

  fn combined(output: &Output) -> String {
    let mut text = String::from_utf8_lossy(&output.stdout).into_owned();
    text.push_str(&String::from_utf8_lossy(&output.stderr));

    text.replace("\r\n", "\n")
  }

  /// Asserts the executable aborted with the house launch-failure
  /// message naming `name` and `reason`.
  fn assert_aborted(output: &Output, name: &str, reason: &str) {
    let text = combined(output);
    let expected = format!("  Launch aborted for {name}\n  Reason: {reason}");

    assert!(
      text.contains("(Zuri):") && text.contains(&expected),
      "\n--- expected to contain ---\n{expected}\n--- actual ---\n{text}\n"
    );
    assert_eq!(output.status.code(), Some(1), "launch failures exit 1");
  }

  fn assert_ran(output: &Output, expected: &str) {
    let text = combined(output);

    assert!(
      output.status.success(),
      "\n{} did not exit cleanly\n--- output ---\n{text}\n",
      env!("CARGO_BIN_EXE_zuri")
    );
    assert!(
      text.contains(expected),
      "\n--- expected to contain ---\n{expected}\n--- actual ---\n{text}\n"
    );
  }

  /// Reports the arguments the script was handed, which is the shape
  /// `os.args[2,]` is documented to have.
  const REPORT_ARGS: &str = "import os\n\necho 'ran ${os.args[2,]}'\n";

  #[test]
  fn version_reports_the_build_without_running_anything() {
    let dir = case("version");
    // An entrypoint that would announce itself if `--version` were ever
    // read as a path or a command.
    write(&dir.join("index.zu"), "echo 'ran the entrypoint'\n");

    let output = zuri(&dir, &["--version"]);
    let text = combined(&output);

    assert!(output.status.success(), "--version must exit 0\n{text}");
    assert!(
      !text.contains("ran the entrypoint"),
      "--version must not launch anything\n--- actual ---\n{text}\n"
    );

    // The same two lines the REPL opens with, minus its own note that
    // it is interactive.
    let mut lines = text.lines();
    let version = lines.next().unwrap_or_default();

    assert!(
      version.starts_with("Zuri ") && version.contains("(running on ZuriVM "),
      "\n--- actual ---\n{text}\n"
    );
    assert!(
      !version.contains("REPL"),
      "--version must not claim to be interactive\n--- actual ---\n{text}\n"
    );
    assert!(
      lines.next().unwrap_or_default().starts_with("Build No. => "),
      "\n--- actual ---\n{text}\n"
    );
  }

  /// The line a help listing gives one command, without its indent.
  fn listed<'a>(text: &'a str, name: &str) -> Option<&'a str> {
    text
      .lines()
      .map(str::trim_end)
      .find(|line| line.starts_with(&format!("  {name}")))
      .map(|line| line.trim_start())
  }

  /// A command that says what it is, the way a real one does.
  fn command_source(name: &str, description: &str) -> String {
    format!("/**\n * @command {name}\n * @description {description}\n */\n\necho 'ran {name}'\n")
  }

  #[test]
  fn help_lists_the_commands_the_runtime_ships() {
    let dir = case("help_shipped");
    // Would announce itself if `--help` ever launched anything.
    write(&dir.join("index.zu"), "echo 'ran the entrypoint'\n");

    let output = zuri(&dir, &["--help"]);
    let text = combined(&output);

    assert!(output.status.success(), "--help must exit 0\n{text}");
    assert!(
      !text.contains("ran the entrypoint"),
      "--help must not launch anything\n--- actual ---\n{text}\n"
    );

    // It opens with what `--version` reports, then the usage.
    assert!(text.starts_with("Zuri "), "\n--- actual ---\n{text}\n");
    assert!(text.contains("Build No. => "), "\n--- actual ---\n{text}\n");
    assert!(text.contains("Usage: zuri"), "\n--- actual ---\n{text}\n");
    assert!(text.contains("\nCOMMANDS:\n"), "\n--- actual ---\n{text}\n");

    // `format` ships in `cmds/`, and must arrive described.
    let line = listed(&text, "format")
      .unwrap_or_else(|| panic!("format was not listed\n--- actual ---\n{text}\n"));

    assert!(
      line.len() > "format".len(),
      "format was listed with no description: {line:?}"
    );
  }

  #[test]
  fn the_short_flags_match_the_long_ones() {
    let dir = case("short_flags");

    assert_eq!(
      combined(&zuri(&dir, &["-h"])),
      combined(&zuri(&dir, &["--help"])),
      "-h must print exactly what --help prints"
    );
    assert_eq!(
      combined(&zuri(&dir, &["-v"])),
      combined(&zuri(&dir, &["--version"])),
      "-v must print exactly what --version prints"
    );
  }

  #[test]
  fn help_lists_a_projects_own_commands() {
    let dir = case("help_project");
    write(
      &dir.join(".zuri/cmds/lint.zu"),
      &command_source("lint", "Check the project for the mistakes CI rejects."),
    );
    // A description long enough to wrap, which is written as an
    // indented continuation of the tag.
    write(
      &dir.join(".zuri/cmds/deploy/index.zu"),
      "/**\n * @command deploy\n * @description Ship the current build to staging,\n *    then wait for the health check.\n */\n",
    );

    let output = zuri(&dir, &["--help"]);
    let text = combined(&output);

    assert!(text.contains("\nPROJECT COMMANDS:\n"), "\n--- actual ---\n{text}\n");
    assert_eq!(
      listed(&text, "lint"),
      Some("lint    Check the project for the mistakes CI rejects."),
      "\n--- actual ---\n{text}\n"
    );

    // The wrapped continuation arrives joined onto one line.
    assert_eq!(
      listed(&text, "deploy"),
      Some("deploy  Ship the current build to staging, then wait for the health check."),
      "\n--- actual ---\n{text}\n"
    );
  }

  #[test]
  fn help_leaves_out_a_project_command_a_shipped_one_hides() {
    let dir = case("help_shadowed");
    write(
      &dir.join(".zuri/cmds/format.zu"),
      &command_source("format", "The project copy, which can never run."),
    );

    let text = combined(&zuri(&dir, &["--help"]));

    assert!(
      !text.contains("The project copy"),
      "a command that can never run was listed\n--- actual ---\n{text}\n"
    );
    assert!(
      !text.contains("PROJECT COMMANDS"),
      "the section must go entirely when it would be empty\n--- actual ---\n{text}\n"
    );
  }

  #[test]
  fn help_lists_a_command_that_describes_nothing() {
    let dir = case("help_undescribed");
    write(&dir.join(".zuri/cmds/bare.zu"), "echo 'bare'\n");

    let text = combined(&zuri(&dir, &["--help"]));

    assert_eq!(
      listed(&text, "bare"),
      Some("bare"),
      "a command with no doc block must still be listed by name\n--- actual ---\n{text}\n"
    );
  }

  #[test]
  fn run_uses_the_working_directory_entrypoint() {
    let dir = case("run_cwd_entry");
    write(&dir.join("index.zu"), REPORT_ARGS);

    assert_ran(&zuri(&dir, &["run"]), "ran []");
  }

  #[test]
  fn run_without_an_entrypoint_aborts() {
    let dir = case("run_cwd_no_entry");
    let output = zuri(&dir, &["run"]);

    // The working directory is named in full, since the user typed no
    // path for the message to quote back.
    let text = combined(&output);
    assert!(
      text.contains("Reason: No entrypoint found in the directory"),
      "\n--- actual ---\n{text}\n"
    );
    assert_eq!(output.status.code(), Some(1));
  }

  #[test]
  fn run_launches_a_script() {
    let dir = case("run_script");
    write(&dir.join("main.zu"), REPORT_ARGS);

    assert_ran(&zuri(&dir, &["run", "main.zu"]), "ran []");
  }

  #[test]
  fn run_launches_a_directory_entrypoint() {
    let dir = case("run_directory");
    write(&dir.join("package").join("index.zu"), REPORT_ARGS);

    assert_ran(&zuri(&dir, &["run", "package"]), "ran []");
  }

  #[test]
  fn run_on_a_directory_without_an_entrypoint_aborts() {
    let dir = case("run_directory_no_entry");
    fs::create_dir_all(dir.join("package")).expect("failed to create the package directory");

    assert_aborted(
      &zuri(&dir, &["run", "package"]),
      "package",
      "No entrypoint found in the directory",
    );
  }

  #[test]
  fn run_on_a_missing_path_aborts() {
    let dir = case("run_missing");

    assert_aborted(
      &zuri(&dir, &["run", "nowhere.zu"]),
      "nowhere.zu",
      "No such file or directory",
    );
  }

  #[test]
  fn run_on_a_file_that_is_not_a_script_aborts() {
    let dir = case("run_not_a_script");
    write(&dir.join("notes.txt"), "echo 'hello'\n");

    assert_aborted(
      &zuri(&dir, &["run", "notes.txt"]),
      "notes.txt",
      "Not a Zuri script",
    );
  }

  #[test]
  fn run_forwards_the_rest_to_the_script() {
    let dir = case("run_forwards");
    write(&dir.join("main.zu"), REPORT_ARGS);

    assert_ran(
      &zuri(&dir, &["run", "main.zu", "build", "--force", "-n"]),
      "ran [build, --force, -n]",
    );
  }

  #[test]
  fn a_flag_after_run_belongs_to_the_entrypoint() {
    let dir = case("run_leading_flag");
    write(&dir.join("index.zu"), REPORT_ARGS);

    assert_ran(&zuri(&dir, &["run", "--force"]), "ran [--force]");
  }

  #[test]
  fn a_project_command_runs_from_a_script() {
    let dir = case("command_script");
    write(&dir.join(".zuri/cmds/greet.zu"), REPORT_ARGS);

    assert_ran(&zuri(&dir, &["greet", "world", "--loud"]), "ran [world, --loud]");
  }

  #[test]
  fn a_project_command_runs_from_a_directory() {
    let dir = case("command_directory");
    write(&dir.join(".zuri/cmds/greet/index.zu"), REPORT_ARGS);

    assert_ran(&zuri(&dir, &["greet", "world"]), "ran [world]");
  }

  #[test]
  fn a_command_directory_wins_over_a_command_file() {
    let dir = case("command_directory_precedence");
    write(&dir.join(".zuri/cmds/greet.zu"), "echo 'ran the file'\n");
    write(&dir.join(".zuri/cmds/greet/index.zu"), REPORT_ARGS);

    let output = zuri(&dir, &["greet", "world"]);
    let text = combined(&output);

    assert!(
      !text.contains("ran the file"),
      "a command file shadowed the directory beside it\n--- actual ---\n{text}\n"
    );
    assert_ran(&output, "ran [world]");
  }

  #[test]
  fn a_command_directory_without_an_entrypoint_is_not_a_command() {
    let dir = case("command_directory_no_entry");
    fs::create_dir_all(dir.join(".zuri/cmds/greet")).expect("failed to create the command");

    assert_aborted(&zuri(&dir, &["greet"]), "greet", "Unknown command");
  }

  #[test]
  fn a_command_file_answers_for_an_empty_directory_beside_it() {
    let dir = case("command_directory_falls_through");
    write(&dir.join(".zuri/cmds/greet.zu"), REPORT_ARGS);
    fs::create_dir_all(dir.join(".zuri/cmds/greet")).expect("failed to create the command");

    assert_ran(&zuri(&dir, &["greet", "world"]), "ran [world]");
  }

  #[test]
  fn a_shipped_command_wins_over_a_project_one() {
    let dir = case("command_precedence");
    write(&dir.join(".zuri/cmds/format.zu"), "echo 'the project copy'\n");

    let output = zuri(&dir, &["format", "--help"]);
    let text = combined(&output);

    assert!(
      !text.contains("the project copy"),
      "a project command shadowed one the runtime ships\n--- actual ---\n{text}\n"
    );
    assert_ran(&output, "Usage: format");
  }

  #[test]
  fn an_unknown_command_aborts() {
    let dir = case("command_unknown");

    assert_aborted(&zuri(&dir, &["nowhere"]), "nowhere", "Unknown command");
  }

  #[test]
  fn a_path_never_names_a_command() {
    let dir = case("command_traversal");
    write(&dir.join(".zuri/cmds/greet.zu"), REPORT_ARGS);

    // Both spellings would resolve inside the command directory if the
    // name were joined onto it unchecked.
    assert_aborted(&zuri(&dir, &["./greet"]), "./greet", "Unknown command");
    assert_aborted(
      &zuri(&dir, &["../cmds/greet"]),
      "../cmds/greet",
      "Unknown command",
    );
  }

  #[test]
  fn a_script_is_not_launched_as_a_command() {
    let dir = case("command_is_not_a_path");
    write(&dir.join("main.zu"), REPORT_ARGS);

    // `run` is the only way to reach a file; a bare path is a command
    // name that happens to contain a dot.
    assert_aborted(&zuri(&dir, &["main.zu"]), "main.zu", "Unknown command");
  }
}
